    for t in T:
        r = dict(L0=t[0], L1=t[1], a0=t[2], u=t[3], x=t[4], v=t[5], w=t[6], Cpr=t[7], Bpr=t[8],
                 tab=dict(b1=t[9], b2=t[10], d3=t[11], d4=t[12], d5=t[13], c1=t[14], c2=t[15], c3=t[16], c4=t[17], c5=t[18]),
                 zfr=her_zfr(t[0]), lam='1')
        out.append(r)
    if include_kv:
        t = KV
        out.append(dict(L0=t[0], L1=t[1], a0=t[2], u=t[3], x=t[4], v=t[5], w=t[6], Cpr=t[7], Bpr=t[8], tab=None,
                        zfr=her_zfr(t[0]), lam='1'))
    return out
